-- The whole of SEBI's BRSR format as questions (owner's request, 2026-10-09;
-- .grill/full-brsr-report-decisions.md, SCHEMA_DEVIATIONS.md D32). Until now only the ten indicators the
-- app has measured data for existed. The report now prints every question of Sections A, B and C in SEBI's
-- order, as the L&T FY2025-26 reference report does (ps_documents/provided_docs): the app fills what it
-- measures, an Admin types the written disclosures once per financial year, and anything left empty prints
-- "Not reported". Question wording is SEBI's, as printed in that reference report.

alter table public.brsr_indicators
  -- 'data': answered from approved records through metric mappings. 'statement': typed by an Admin.
  add column answer_kind text not null default 'data'
    constraint brsr_indicators_answer_kind check (answer_kind in ('data', 'statement')),
  -- Section C: the NGRBC principle (1 to 9).
  add column principle smallint constraint brsr_indicators_principle check (principle between 1 and 9),
  -- Sections A and B: the sub-heading the question is printed under.
  add column part text,
  add column sort_order integer not null default 0;

-- A typed answer to one question for one financial year (the year it starts in: 2026 = April 2026 to
-- March 2027). Any question may carry one — a 'data' question's answer is printed under its figures.
create table public.brsr_disclosures (
  id uuid primary key default gen_random_uuid(),
  brsr_indicator_id uuid not null references public.brsr_indicators (id),
  financial_year integer not null check (financial_year between 2000 and 2100),
  answer text not null check (length(btrim(answer)) between 1 and 20000),
  updated_by uuid not null references public.users (id),
  updated_at timestamptz not null default now(),
  unique (brsr_indicator_id, financial_year)
);

-- Read and written by the server only, like org_levels.
alter table public.brsr_disclosures enable row level security;
revoke all on public.brsr_disclosures from anon, authenticated;

insert into public.brsr_indicators
