  ('C', 'P6-L6', 'Disclose any significant adverse impact to the environment, arising from the value chain of the entity. What mitigation or adaptation measures have been taken by the entity in this regard.', 'leadership', 6, null, 6506, '{}', 'Principle 6, Leadership Indicator 6.'),
  ('C', 'P6-L7', 'Percentage of value chain partners (by value of business done with such partners) that were assessed for environmental impacts.', 'leadership', 6, null, 6507, '{}', 'Principle 6, Leadership Indicator 7.'),
