  ('C', 'P9-E3', 'Number of consumer complaints in respect of the following: data privacy; advertising; cyber-security; delivery of essential services; restrictive trade practices; unfair trade practices; other.', 'essential', 9, null, 9003, '{}', 'Principle 9, Essential Indicator 3.'),
